  getr R1 (reg 1) = Z_to_bv 64 r -> (forall x, In x PMK.cs_all -> getr R1 (reg x) = getr R0 (reg x)) ->
  ae_at M1 oa ov osk st' -> ae_ok st' -> ec_state M1 oec b1 cat -> PMST.base_ok RSEGS AD M1 -> err_ok M1 e1 ->
