Lemma STORE_C (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) :
  tnew = 0 -> n < 2 ^ k ->
  getr R (reg 2) = Z_to_bv 64 (S - 112) -> getr R (reg 8) = Z_to_bv 64 oa -> getr R (reg 10) = Z_to_bv 64 e0 -> kept0 R ->
  getr R (reg 21) = getr R0 (reg 11) -> getr R (reg 18) = Z_to_bv 64 oec ->
  saves M -> cme M -> world M -> adaptor_at M oa ov ast -> xinv M kb kbb ->
