(* [comment removed for export] *)
Lemma PBOPEN (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (bX kX : Z) (kb1 : PM.vstr) (g1 : Z) (kbb1 : list Z) (cr : credit) :
  tnew = 1 ->
  getr R (reg 1) = Z_to_bv 64 0x39b4c -> getr R (reg 2) = Z_to_bv 64 (S - 112) -> getr R (reg 8) = Z_to_bv 64 oa -> kept0 R ->
  getr R (reg 10) = Z_to_bv 64 (oa + 48) -> getr R (reg 11) = Z_to_bv 64 CHB ->
  saves M -> cme M -> world M -> adaptor_at M oa ov (stQ bX kX kb1 g1) -> PQM.ks_ok PQM.SMB kb1 g1 -> PM.vs_size kb1 <= PM.vs_size kb + 1 ->
  xinv M kb1 kbb1 ->
  PMSP.credit_keep cr0 cr (PQM.pot_adaptor L ast) (PQM.pot_adaptor L (stQ bX kX kb1 g1)) -> model_but_vm model0 model ->
  hi_heap HI (PQM.aown (stQ bX kX kb1 g1) ++ LBXe) cr M (m_vmmaps model) ->
