Lemma MCST (x : arm) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (B0 : Z) (kb1 : PM.vstr) (g1 : Z) (kbb1 : list Z) (cr : credit) :
  n = 2 ^ k -> k <= 10 -> armregs x R kb1 g1 kbb1 ->
  getr R (reg 1) = Z_to_bv 64 (upc x) -> getr R (reg 10) = Z_to_bv 64 B0 -> getr R (reg 11) = Z_to_bv 64 b -> getr R (reg 12) = Z_to_bv 64 (24 * 2 ^ k) ->
  getr R (reg 2) = Z_to_bv 64 (S - 112) -> getr R (reg 8) = Z_to_bv 64 oa -> getr R (reg 9) = Z_to_bv 64 B0 ->
  getr R (reg (sreg x)) = Z_to_bv 64 (B0 + 24 * (n + 1)) -> getr R (reg (creg x)) = Z_to_bv 64 (B0 + 24 * 2 ^ (k + 1)) -> kept0 R ->
  saves M -> cme M -> world M -> adaptor_at M oa ov (stX lv b k kb1 g1) -> PQM.ks_ok PQM.SMB kb1 g1 -> PM.vs_size kb1 <= PM.vs_size kb + 1 ->
  xinv M kb1 kbb1 ->
  L5.defined M B0 (24 * 2 ^ (k + 1)) -> B0 mod 16 = 0 -> alvl_at M (B0 + 24 * 2 ^ k) cnew ->
  PMSP.credit_keep cr0 cr (PQM.pot_adaptor L ast) (PQM.pot_adaptor L (stQ B0 (k + 1) kb1 g1)) -> model_but_vm model0 model ->
  hi_heap HI ((B0, 24 * 2 ^ (k + 1)) :: PQM.aown (stX lv b k kb1 g1) ++ LBXe) cr M (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0xb9978 M model) K.
