  getr R (reg 1) = Z_to_bv 64 0x3ca44 -> getr R (reg 10) = Z_to_bv 64 (24 * 2 ^ (k + 1)) -> getr R (reg 2) = Z_to_bv 64 (S - 128) ->
  getr R (reg 8) = Z_to_bv 64 (2 ^ (k + 1)) -> getr R (reg 9) = Z_to_bv 64 (oa + 72) -> getr R (reg (sreg x)) = Z_to_bv 64 (24 * 2 ^ k) -> kept0 R ->
